# %% [markdown]
# # Analysis of CBF Parameter Sweep
# This script reads the datasets generated by the SLURM array parameter sweep and plots the metrics.

# %%
import os
import yaml
import numpy as np
import pandas as pd
import matplotlib.pyplot as plt
import seaborn as sns
from datasets import load_from_disk

# %%
base_dir = "/home/emunoz/dev/safe-nav-smoke/" #
config_path = os.path.join(os.path.dirname(os.path.dirname(os.path.abspath(__file__))), "config_sweep.yaml")

with open(config_path, "r") as f:
    cfg = yaml.safe_load(f)

sweep_param = cfg["sweep_param"]
sweep_values = cfg["sweep_values"]

repo_root = "/home/emunoz/dev/safe-nav-smoke/" #os.path.dirname(os.path.dirname(os.path.dirname(base_dir)))
project_name = cfg.get("project_name", "single_agent_experiment")
sub_project_name = cfg.get("sub_project_name", "cbf_sweep")

outputs_dir = os.path.join(repo_root, "outputs", project_name, sub_project_name, sweep_param)
print(f"Analyzing Sweep Parameter: {sweep_param}")
print(f"Expected Values: {sweep_values}")
print(f"Looking in: {outputs_dir}")

# %% [markdown]
# ## 1. Data Collection

# %%
all_data = []

# Fetch Playback dataset to get dynamic grid resolution
playback_data_path = cfg.get("simulator", {}).get("data_path", "data/structured_smoke_slow")
playback_ds_path = os.path.join(repo_root, playback_data_path) if not os.path.isabs(playback_data_path) else playback_data_path

playback_ds = load_from_disk(playback_ds_path)
first_row = playback_ds[0]
# Use config values or fail if they don't exist
RESOLUTION = float(cfg.get("simulator", {}).get("resolution")) if "resolution" in cfg.get("simulator", {}) else float(first_row["resolution"])
Y_SIZE = float(cfg.get("simulator", {}).get("y_size")) if "y_size" in cfg.get("simulator", {}) else float(first_row["y_size"])
X_SIZE = float(cfg.get("simulator", {}).get("x_size")) if "x_size" in cfg.get("simulator", {}) else float(first_row["x_size"])

H = int(Y_SIZE / RESOLUTION)
W = int(X_SIZE / RESOLUTION)
print(f"Grid setup: {H}x{W} at {RESOLUTION}m resolution")

for val in sweep_values:
    val_str = f"{val:.4f}".replace(".", "_")
    ds_dir = os.path.join(outputs_dir, f"val_{val_str}")
    
    if not os.path.exists(ds_dir):
        print(f"Warning: Results for {val} not found in {ds_dir}")
        continue
        
    try:
        ds = load_from_disk(ds_dir)
        ds = ds.with_format("numpy")
    except Exception as e:
        print(f"Failed to load dataset for {val}: {e}")
        continue
        
    print(f"Loaded {len(ds)} transitions for {sweep_param}={val}")
        
    episodes = []
    current_ep = []
    for row in ds:
        current_ep.append(row)
        if row["terminations"] or row["truncations"]:
            episodes.append(current_ep)
            current_ep = []
            
    if len(current_ep) > 0:
        episodes.append(current_ep)
        
    for idx, ep in enumerate(episodes):
        smoke_on_robot_vals = []
        reached_goal = False
        time_taken = len(ep) * 0.1
        
        for transition in ep:
            if "smoke_in_robot" in transition:
                smoke_val = transition["smoke_in_robot"]
            else:
                loc = transition["obs_location"]
                readings = transition["obs_readings"]
                
                y_coords = (loc[1] / RESOLUTION) - 0.5
                x_coords = (loc[0] / RESOLUTION) - 0.5
                y_idx = int(np.clip(round(y_coords), 0, H-1))
                x_idx = int(np.clip(round(x_coords), 0, W-1))
                
                try:
                    full_map = readings.reshape(H, W)
                    smoke_val = full_map[y_idx, x_idx]
                except:
                    smoke_val = 0.0
                
            smoke_on_robot_vals.append(smoke_val)
            if transition["reward"] > 0.0:
                reached_goal = True
                
        max_smoke = max(smoke_on_robot_vals) if smoke_on_robot_vals else np.nan
        mean_smoke = np.mean(smoke_on_robot_vals) if smoke_on_robot_vals else np.nan
        
        all_data.append({
            'Sweep Value': val,
            'Episode': idx,
            'Max Smoke': max_smoke,
            'Mean Smoke': mean_smoke,
            'Time to Goal': time_taken,
            'Reached Goal': reached_goal
        })

df = pd.DataFrame(all_data)
if df.empty:
    print("No data extracted!")
else:
    print(f"Successfully loaded {len(df)} episodes.")

# %% [markdown]
# ## 2. Summary Statistics

# %%
if not df.empty:
    summary = df.groupby('Sweep Value').agg(
        Success_Rate=('Reached Goal', lambda x: x.mean() * 100),
        Avg_Max_Smoke=('Max Smoke', 'mean'),
        Avg_Mean_Smoke=('Mean Smoke', 'mean'),
        Avg_Time=('Time to Goal', lambda x: df.loc[x.index][df.loc[x.index]['Reached Goal']]['Time to Goal'].mean())
    ).round(2)
    print(summary)

# %% [markdown]
# ## 3. Visualizations

# %%
plt.rcParams.update({
    "font.family": "serif",
    "font.size": 12,
    "axes.labelsize": 14,
    "axes.grid": True,
    "grid.alpha": 0.5,
})

if not df.empty:
    fig, axes = plt.subplots(1, 4, figsize=(24, 5))
    
    # Success Rate
    sns.barplot(data=summary, x=summary.index, y='Success_Rate', ax=axes[0])
    axes[0].set_title("Success Rate vs. Threshold")
    axes[0].set_ylabel("Success Rate (%)")
    axes[0].set_xlabel(sweep_param)
    axes[0].set_ylim(0, 110)
    
    # Max Smoke & Time (only successful episodes)
    success_df = df[df['Reached Goal']]
    if not success_df.empty:
        sns.boxplot(data=success_df, x='Sweep Value', y='Max Smoke', ax=axes[1])
        axes[1].set_title("Max Smoke Inhaled (Successful Ops)")
        axes[1].set_xlabel(sweep_param)

        sns.boxplot(data=success_df, x='Sweep Value', y='Mean Smoke', ax=axes[2])
        axes[2].set_title("Mean Smoke Inhaled (Successful Ops)")
        axes[2].set_xlabel(sweep_param)
        
        sns.boxplot(data=success_df, x='Sweep Value', y='Time to Goal', ax=axes[3])
        axes[3].set_title("Time to Goal (s)")
        axes[3].set_xlabel(sweep_param)
        
    plt.tight_layout()
    plt.show()

# %%

# %% [markdown]
# ## 4. Mathematical Pareto Optimization (Elbow Point Calculation)

# %%
if not df.empty:
    # 1. Preparar el DataFrame agrupado
    summary_df = summary.reset_index()

    # 2. Normalizar las métricas críticas entre 0 y 1
    s_min, s_max = summary_df['Avg_Mean_Smoke'].min(), summary_df['Avg_Mean_Smoke'].max()
    t_min, t_max = summary_df['Avg_Time'].min(), summary_df['Avg_Time'].max()

    s_denom = (s_max - s_min) if s_max != s_min else 1.0
    t_denom = (t_max - t_min) if t_max != t_min else 1.0

    summary_df['Norm_Smoke'] = (summary_df['Avg_Mean_Smoke'] - s_min) / s_denom
    summary_df['Norm_Time'] = (summary_df['Avg_Time'] - t_min) / t_denom
    # Tasa de fallo (100% - Success_Rate) convertida a una escala de 0 a 1
    summary_df['Norm_Failure'] = (100.0 - summary_df['Success_Rate']) / 100.0

    # 3. Definir pesos de balance (Priorizando viabilidad del solver QP y seguridad aérea)
    w_safety = 0.3      # Peso para mitigar el humo inhalado
    w_viability = 0.3   # Peso para mantener alto Success Rate (evitar QPs infeisbles)
    w_time = 0.3        # Peso para el tiempo de misión

    # 4. Calcular la pérdida total usando la Distancia Euclidiana Ponderada al punto ideal (0,0,0)
    summary_df['Pareto_Loss'] = np.sqrt(
        w_safety * (summary_df['Norm_Smoke']**2) +
        w_time * (summary_df['Norm_Time']**2) +
        w_viability * (summary_df['Norm_Failure']**2)
    )

    # 5. Encontrar el índice del parámetro óptimo
    optimal_row = summary_df.loc[summary_df['Pareto_Loss'].idxmin()]
    optimal_beta = optimal_row['Sweep Value']

    # 6. Imprimir resultados numéricos en consola
    print("\n" + "="*60)
    print("MATHEMATICAL PARETO ANALYSIS RESULTS")
    print("="*60)
    print(f"Weights used -> Safety: {w_safety}, Viability: {w_viability}, Time: {w_time}")
    print(f"The mathematically optimal 'Elbow Point' is: beta = {optimal_beta}")
    print("-"*60)
    print(f"Performance at optimal point (beta = {optimal_beta}):")
    print(f"  - Success Rate:      {optimal_row['Success_Rate']}%")
    print(f"  - Avg Mean Smoke:     {optimal_row['Avg_Mean_Smoke']}")
    print(f"  - Avg Time to Goal:  {optimal_row['Avg_Time']} s")
    print("="*60 + "\n")

# %%
